SELECT id, session_id, event_time, duration_sec, SUM(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec, ROUND(AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), 2) AS duration_sec_moving_avg_4 FROM web_events;
